import {parcels,DIMENSIONS,RULE_VERSION,filterParcels,evaluate,explanation,reportMarkdown} from './domain.js';
const $=s=>document.querySelector(s);
const state={selected:parcels[0].id,compared:[],results:new Map(),query:'',use:'',zoom:1,page:'workbench'};
const fmt=n=>n.toLocaleString('zh-CN');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const current=()=>parcels.find(p=>p.id===state.selected);
let toastTimer;
function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3200);}
function showDialog(title,content){$('#dialog-title').textContent=title;$('#dialog-content').textContent=content;$('#info-dialog').showModal();}
function go(page){state.page=page;for(const name of ['workbench','compare','report'])$(`#${name}-page`).hidden=page!==name;document.querySelectorAll('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);b.setAttribute('aria-current',b.dataset.page===page?'page':'false');});$('#page-title').innerHTML={workbench:'空间评估工作台',compare:'地块比较',report:'地块评估摘要'}[page]+'<span class="title-period" aria-hidden="true">.</span>';if(page==='compare')renderCompare();if(page==='report')renderReport();}
function selectParcel(id){if(!parcels.some(p=>p.id===id))throw new Error('地块不存在');state.selected=id;$('#answer').textContent='已切换当前地块。运行评估或选择一个问题，查看该地块的解释。';render();return {parcelId:id,name:current().name};}
function addCompare(id){if(!parcels.some(p=>p.id===id))throw new Error('地块不存在');if(state.compared.includes(id)){state.compared=state.compared.filter(x=>x!==id);toast('已移出比较清单');}else{if(state.compared.length===3){toast('最多比较3宗地块，请先移除一宗');return;}state.compared.push(id);toast('已加入比较清单');}render();if(state.page==='compare')renderCompare();}
function runEvaluation(id){const p=parcels.find(p=>p.id===id);if(!p)throw new Error('地块不存在');const r=evaluate(p);state.results.set(id,r);render();if(state.page==='compare')renderCompare();if(state.page==='report')renderReport();return r;}
function renderMetrics(){const done=[...state.results.values()];const high=done.filter(r=>r.total!==null&&r.total>=60).length;$('#metrics').innerHTML=[['片区地块',parcels.length,'宗'],['土地总面积',(parcels.reduce((s,p)=>s+p.area,0)/10000).toFixed(2),'公顷'],['已完成演示评估',done.length,`/ ${parcels.length} 宗`],['较高关注度',high,'宗 · ≥60分']].map(([label,value,unit])=>`<div class="metric"><div class="metric-label">${label}</div><div class="metric-value">${value}<small>${unit}</small></div></div>`).join('');}
function renderMap(){const visible=filterParcels(state.query,state.use);const ids=new Set(visible.map(p=>p.id));$('#result-count').textContent=`${visible.length} / ${parcels.length} 宗`;$('#map-world').innerHTML=`<defs><pattern id="atlas-grid" width="35" height="35" patternUnits="userSpaceOnUse"><path d="M35 0H0V35" fill="none" stroke="#7b98a1" stroke-opacity=".08" stroke-width="1"/></pattern></defs><rect width="1000" height="740" fill="#1c2b35"/><rect width="1000" height="740" fill="url(#atlas-grid)"/><g fill="none" stroke="#334650" stroke-width="19"><path d="M0 115H1000M0 267H1000M0 404H1000M0 554H1000M60 0V740M290 0V740M461 0V740M715 0V740M925 0V740"/></g><g fill="#2b4743" opacity=".7"><path d="M20 580h330v95H20zM750 595h190v95H750z"/><path d="M70 40h370v45H70z"/></g><path d="M637 -40C565 120 720 216 657 359S654 593 723 780" fill="none" stroke="#314958" stroke-width="92"/><path d="M637 -40C565 120 720 216 657 359S654 593 723 780" fill="none" stroke="#213945" stroke-width="66"/><g fill="#829da9" font-size="15" letter-spacing="5"><text x="350" y="122">滨 河 路</text><text x="125" y="410">更 新 大 道</text><text x="145" y="635" fill="#91aba1">滨 河 绿 地</text></g>${parcels.map(p=>{const active=state.selected===p.id;const r=state.results.get(p.id);const fill=active?'#dbff73':r?.total>=60?'#a991d0':r?'#558985':'#354d5a';return `<g opacity="${ids.has(p.id)?1:.12}" ${ids.has(p.id)?'':'pointer-events="none"'}><rect class="parcel ${active?'selected':''}" x="${p.x}" y="${p.y}" width="${p.w}" height="${p.h}" rx="2" fill="${fill}" data-map-id="${p.id}" tabindex="${ids.has(p.id)?0:-1}" role="button" aria-label="选择${p.name} ${p.id}" aria-pressed="${active}"/><text class="map-label ${active?'selected':''}" x="${p.x+p.w/2}" y="${p.y+p.h/2-2}" text-anchor="middle">${p.id}</text><text class="parcel-subtitle ${active?'selected':''}" x="${p.x+p.w/2}" y="${p.y+p.h/2+22}" text-anchor="middle">${p.use} / ${(p.area/10000).toFixed(2)} ha</text></g>`;}).join('')}`;$('#map-world').style.transform=`scale(${state.zoom})`;$('#parcel-list').innerHTML=visible.length?visible.map(p=>{const r=state.results.get(p.id);return `<button class="parcel-row ${state.selected===p.id?'active':''}" data-select="${p.id}" aria-pressed="${state.selected===p.id}"><strong>${esc(p.name)}</strong><span class="row-meta">${p.id} · ${p.use} · ${fmt(p.area)} m²</span><span class="row-state">${r?(r.total===null?'资料不完整':r.total.toFixed(1)+' 分'):'未评估'}</span></button>`;}).join(''):'<div class="empty-state">没有符合条件的地块。<br>可清空关键词或点击重置。</div>';}
function renderDetail(){const p=current(),r=state.results.get(p.id),visible=filterParcels(state.query,state.use).some(x=>x.id===p.id);$('#detail').innerHTML=`<div class="detail-main"><div class="detail-kicker"><span>地块档案 / ${p.id}</span><span class="small-tag">${p.use}用地</span></div><h2>${esc(p.name)}</h2><p class="detail-subtitle">滨河更新示范片区 · 演示地块</p>${!visible?'<p class="notice">当前地块不在筛选结果中，详情仍保留。</p>':''}<dl class="facts"><div><dt>土地面积</dt><dd>${fmt(p.area)} <small>m²</small></dd></div><div><dt>现状容积率</dt><dd>${(p.buildingArea/p.area).toFixed(2)}</dd></div><div><dt>空置率</dt><dd>${p.vacancy===null?'待补充':p.vacancy+'%'}</dd></div><div><dt>资料日期</dt><dd>${p.date}</dd></div></dl><div class="actions"><button class="primary" id="evaluate">${r?'重新评估':'运行评估'}</button><button class="quiet" id="compare-add">${state.compared.includes(p.id)?'移出比较':'＋ 加入比较'}</button></div></div><section class="assessment"><div class="section-title"><h3>多维更新关注度</h3><span class="small-tag">${RULE_VERSION}</span></div>${r?`<div class="score-line"><div class="score-orbit" style="--progress:${r.total??0}%" aria-label="更新关注度 ${r.total===null?'资料不足':r.total+'分'}"><strong class="score-number">${r.total===null?'—':r.total.toFixed(1)}</strong></div><div class="score-meta">${r.total===null?'资料不足':r.total>=60?'较高关注度':'一般关注度'}<small>指标覆盖率 ${r.coverage}% · 仅供演示</small></div></div>${DIMENSIONS.map((d,i)=>`<div class="bar-row"><button data-evidence="${i}">${d}</button><div class="bar-track"><span style="width:${r.scores[i]??0}%"></span></div><span class="bar-value">${r.scores[i]??'缺失'}</span></div>`).join('')}<p class="notice">${r.missing.length?`待补充：${r.missing.join('、')}。缺失不按0分计算。`:'分值越高，表示越值得进一步研究。综合分不代表更新可行性或投资价值。'}</p>`:'<div class="assessment-empty"><div class="empty-orbit" aria-hidden="true">—</div><p class="muted">运行评估，查看五维画像与每项结论的依据。</p></div><p class="notice">演示规则采用等权重，不是国家或行业评估标准。</p>'}</section>`;}
function render(){renderMetrics();renderMap();renderDetail();$('#compare-count').textContent=state.compared.length;}
function renderCompare(){const ps=state.compared.map(id=>parcels.find(p=>p.id===id));$('#evaluate-compare').disabled=ps.length<2;if(ps.length<2){$('#comparison').innerHTML=`<div class="empty-state"><strong>选择至少2宗地块开始比较</strong>已选择 ${ps.length} 宗。到地图工作台打开地块，点击“加入比较”。<br><button class="primary" data-page="workbench">返回地图选地</button></div>`;return;}const get=(p,i)=>{const r=state.results.get(p.id);return !r?'未评估':r.scores[i]===null?'资料缺失':r.scores[i]+' 分';};const rows=[['现状用途',p=>p.use],['土地面积',p=>fmt(p.area)+' m²'],['建筑面积',p=>fmt(p.buildingArea)+' m²'],['空置率',p=>p.vacancy===null?'资料缺失':p.vacancy+'%'],...DIMENSIONS.map((d,i)=>[d,p=>get(p,i)]),['覆盖率',p=>state.results.has(p.id)?state.results.get(p.id).coverage+'%':'未评估'],['综合关注度',p=>{const r=state.results.get(p.id);return !r?'未评估':r.total===null?'资料不足，暂不排序':r.total.toFixed(1)+' / 100';}],['数据 / 规则',p=>`${p.date}<small>${RULE_VERSION}</small>`]];$('#comparison').innerHTML=`<div class="table-scroll"><table><thead><tr><th>比较指标</th>${ps.map(p=>`<th>${esc(p.name)}<small>${p.id}</small><button class="remove-compare" data-remove="${p.id}">移出比较</button></th>`).join('')}</tr></thead><tbody>${rows.map(([label,fn])=>`<tr><th scope="row">${label}</th>${ps.map(p=>`<td>${fn(p)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="notice">当前全部采用虚构台账与相同规则。高分表示优先研究的关注程度，不表示更适合开发；本原型尚未核验真实规划、权属和建筑安全信息。</p>`;}
function renderReport(){const p=current(),r=state.results.get(p.id);$('#download-report').disabled=!r;$('#print-report').disabled=!r;if(!r){$('#report').innerHTML=`<div class="empty-state"><strong>${esc(p.name)}尚未评估</strong>返回地图工作台运行评估后，可生成该地块的摘要。<br><button class="primary" data-page="workbench">返回地图工作台</button></div>`;return;}$('#report').innerHTML=`<div class="report-brand">UrbanLens</div><h2>${esc(p.name)}评估摘要</h2><p class="demo-tag">演示数据与规则 · 未复核 · 非正式评估报告</p><p>城市更新用地智能评估交互系统<br>${p.id} / ${p.date}</p><h3>01 地块概况</h3><p>现状用途：${p.use}；土地面积：${fmt(p.area)}平方米；建筑面积：${fmt(p.buildingArea)}平方米；现状容积率：${r.ratio.toFixed(2)}。</p><h3>02 多维评估</h3><table><thead><tr><th>维度</th><th>演示关注度得分</th></tr></thead><tbody>${DIMENSIONS.map((n,i)=>`<tr><td>${n}</td><td>${r.scores[i]??'缺失'}</td></tr>`).join('')}</tbody></table><p>指标覆盖率：${r.coverage}%；综合关注度：${r.total===null?'资料不足，暂不输出':r.total.toFixed(1)+' / 100'}。</p><h3>03 解释与核实事项</h3><p>${esc(explanation(p,r,'为什么值得关注？')).replace(/\n/g,'<br>')}</p><p>${esc(explanation(p,r,'哪些资料需要补充？')).replace(/\n/g,'<br>')}</p><h3>04 依据与版本</h3><p>来源：${esc(p.source)}<br>数据版本：${r.dataVersion}<br>规则版本：${r.ruleVersion}<br>当前摘要不包含正式规划及权属核验；DOCX正式报告与复核流程列入后续开发。</p>`;}
function ask(question){const p=current(),r=state.results.get(p.id);$('#answer').innerHTML=`<span class="context">${esc(p.name)} · ${p.id}</span>${esc(explanation(p,r,question))}\n<button class="evidence-link" id="show-source">打开演示来源</button>`;}
const rules=['直线距离÷1500×100，最高100分；距离越远表示服务可达性越需关注。不是步行路网距离。','max(0, min(100, (2−现状容积率)÷2×100))。2为任意演示基准，不代表法定容积率。','符合=20分；待调整=80分；待核实=缺失。标签来自虚构台账，不代表正式产业认定。','调查等级1至4映射为0至100分：(等级−1)÷3×100。虚构等级，不是建筑安全鉴定。','空置率百分数直接映射0至100分；合法0值正常计算；null为缺失。'];
document.addEventListener('click',e=>{const b=e.target.closest('button');const plot=e.target.closest('[data-map-id]');if(plot){selectParcel(plot.dataset.mapId);return;}if(!b)return;if(b.dataset.page)go(b.dataset.page);else if(b.dataset.select)selectParcel(b.dataset.select);else if(b.dataset.remove)addCompare(b.dataset.remove);else if(b.dataset.question)ask(b.dataset.question);else if(b.dataset.evidence!==undefined){const i=Number(b.dataset.evidence),p=current(),r=state.results.get(p.id);const values=[`${p.distance}米`,r.ratio===null?'不可计算':r.ratio.toFixed(2),p.industry,p.condition===null?'缺失':p.condition, p.vacancy===null?'缺失':p.vacancy+'%'];showDialog(DIMENSIONS[i]+' · 计算依据',`原始值：${values[i]}\n得分：${r.scores[i]??'缺失'}\n权重：20%\n\n规则：${rules[i]}\n\n来源：${p.source}\n日期：${p.date}\n版本：${RULE_VERSION}\n\n所有数据与映射仅用于演示。`);}else if(b.id==='evaluate'){runEvaluation(state.selected);toast('演示评估已完成');}else if(b.id==='compare-add')addCompare(state.selected);else if(b.id==='show-source'){const p=current();showDialog('演示地块台账',JSON.stringify(p,null,2));}});
$('#map').addEventListener('keydown',e=>{const p=e.target.closest('[data-map-id]');if(p&&['Enter',' '].includes(e.key)){e.preventDefault();selectParcel(p.dataset.mapId);}});
$('#search').addEventListener('input',e=>{state.query=e.target.value;renderMap();renderDetail();});$('#use-filter').addEventListener('change',e=>{state.use=e.target.value;renderMap();renderDetail();});$('#reset').addEventListener('click',()=>{state.query='';state.use='';$('#search').value='';$('#use-filter').value='';renderMap();renderDetail();});
for(const [id,delta] of [['zoom-in',.2],['zoom-out',-.2],['zoom-fit',0]])$('#'+id).addEventListener('click',()=>{state.zoom=delta?Math.max(.8,Math.min(1.8,state.zoom+delta)):1;$('#map-world').style.transform=`scale(${state.zoom})`;});
$('#evaluate-compare').addEventListener('click',()=>{state.compared.forEach(id=>runEvaluation(id));toast('比较地块已按相同规则评估');});$('#question-form').addEventListener('submit',e=>{e.preventDefault();const q=$('#question').value.trim();if(!q)return;ask(q);$('#question').value='';});
$('#about-btn').addEventListener('click',()=>showDialog('关于 UrbanLens V0.1','这是城市更新用地智能评估交互系统的首轮网页交互原型。\n\n已实现：12宗虚构地块、地图与列表联动、确定性演示评分、来源解释、2至3宗地块比较、摘要下载与打印。\n\n尚未实现：真实地图底图与GIS导入、服务端账号与持久化、真实政策知识库、大模型API、正式评估标准、DOCX生成与复核流程。\n\n本次选择和评估仅保存在当前页面内存，刷新后重置。没有上传或外发地块数据。'));$('#close-dialog').addEventListener('click',()=>$('#info-dialog').close());
$('#download-report').addEventListener('click',()=>{const p=current(),r=state.results.get(p.id);if(!r)return;const url=URL.createObjectURL(new Blob([reportMarkdown(p,r)],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`UrbanLens_${p.id}_演示评估摘要.md`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});$('#print-report').addEventListener('click',()=>{if(state.results.has(state.selected))window.print();});
render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const tools=[{name:'select_urbanlens_parcel',title:'选择UrbanLens地块',description:'选择一个演示地块并打开地图工作台。',inputSchema:{type:'object',properties:{parcelId:{type:'string'}},required:['parcelId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.parcelId!=='string')throw new Error('parcelId必须为字符串');const result=selectParcel(input.parcelId);go('workbench');return result;}},{name:'evaluate_selected_urbanlens_parcel',title:'评估当前演示地块',description:'按DEMO-0.1规则计算当前选中地块并更新页面，不调用真实模型。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('此工具不接受参数');return runEvaluation(state.selected);}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
